/// </summary>
/// <param name="action">Асинхронная функция, возвращающая Task<int>.</param>
/// <param name="attempts">Количество попыток выполнения операции.</param>
/// <returns>Результат выполнения операции (int).</returns>
/// <exception cref="InvalidOperationException">Бросается, если все попытки исчерпаны и операция не удалась.</exception>
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Цикл для выполнения заданного количества попыток
    for (var i = 0; i < attempts; i++)
    {
        try
        {
            // Пытаемся выполнить переданную асинхронную операцию
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            // Если произошла ошибка HTTP и это не последняя попытка:
            // Вычисляем экспоненциальную задержку: 200мс * 2^i
            // Например:
            //   i=0 -> 200 * 1 = 200мс
            //   i=1 -> 200 * 2 = 400мс
            //   i=2 -> 200 * 4 = 800мс
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
