// Функция worker представляет собой функцию-работник, которая обрабатывает задачи из канала jobs.
// Она принимает:
//   - jobs: канал для получения задач (Job)
//   - results: канал для отправки результатов обработки (Result)
//   - wg: указатель на WaitGroup для синхронизации завершения работы
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // Defer wg.Done() гарантирует, что после завершения работы функции
    // будет вызван метод Done() на WaitGroup, что позволит основному потоку
    // узнать о завершении работы этого работника.
    defer wg.Done()

    // Цикл for j := range jobs читает задачи из канала jobs.
    // Цикл завершится, когда канал jobs будет закрыт.
    for j := range jobs {
        // Вызываем функцию process для обработки текущей задачи j.
        // Она возвращает результат r и возможную ошибку err.
        r, err := process(j)

        // Если при обработке задачи произошла ошибка:
        if err != nil {
            // Логируем ошибку с указанием ID задачи и самой ошибки.
            log.Printf("job %d: %v", j.ID, err)
            // Переходим к следующей задаче, игнорируя текущую.
            continue
        }

        // Если ошибок нет, отправляем результат r в канал results.
        // Это блокирующая операция, если канал results заполнен.
        results <- r
    }
}
```

