```typescript
/**
 * Функция debounce (дебаунс) для отложенного выполнения функции.
 *
 * @template T - Тип функции, которую нужно обернуть. Ограничение `T extends (...a: any[]) => void`
 *               означает, что T должна быть функцией, принимающей любые аргументы и возвращающей void.
 * @param fn - Функция, которую нужно обернуть дебаунсом.
 * @param ms - Задержка в миллисекундах, после которой функция будет выполнена.
 * @returns Обернутая функция, которая будет выполняться только после того, как перестанут поступать вызовы
 *          в течение заданного времени (ms).
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Тип ReturnType<typeof setTimeout> гарантирует, что мы используем правильный тип для таймера
  // (в Node.js это number, в браузерах это number или Timeout, в зависимости от окружения).
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и исходная функция fn.
  // Parameters<T> извлекает тип аргументов из типа функции T.
  return (...args: Parameters<T>) => {
    // Если таймер уже установлен (t не undefined), отменяем его.
    // Это позволяет "сбрасывать" таймер при каждом новом вызове,
    // чтобы функция fn выполнялась только после того, как вызовы прекратятся на время ms.
    if (t) clearTimeout(t);

    // Устанавливаем новый таймер.
    // Через ms миллисекунд будет вызвана функция fn с переданными аргументами args.
    // Идентификатор таймера сохраняется в переменной t для возможной отмены в будущем.
    t = setTimeout(() => fn(...args), ms);
  };
}
```

