 * @return Возвращает существующее значение по ключу или новое значение, созданное фабрикой.
 */
fun <K, V> MutableMap<K, V>.getOrPutSafe(key: K, factory: () -> V): V =
    // Обеспечиваем потокобезопасность, блокируя доступ к карте на время выполнения блока.
    synchronized(this) {
        // Пытаемся получить значение по ключу.
        // Если значение отсутствует (null), то:
        this[key] ?:
        // Вызываем фабрику для создания нового значения.
        factory().also {
            // Сохраняем созданное значение в карту под указанным ключом.
            this[key] = it
        }
    }
