/// Парсит строку в формате "ключ=значение;ключ=значение" в HashMap.
///
/// # Аргументы
/// * `s` - входная строка, содержащая пары ключ-значение, разделенные точкой с запятой.
///
/// # Возвращаемое значение
/// HashMap, где ключи — это нижний регистр ключей из входной строки (с обрезанными пробелами),
/// а значения — это значения из входной строки (с обрезанными пробелами).
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    // Разбиваем входную строку по символу ';' на отдельные пары "ключ=значение"
    s.split(';')
        // Для каждой части пытаемся разделить её на ключ и значение по символу '='.
        // Если символ '=' отсутствует, filter_map отбрасывает эту часть (возвращает None).
        .filter_map(|p| p.split_once('='))
        // Преобразуем найденные пары (ключ, значение):
        // - Ключ: убираем пробелы по краям и приводим к нижнему регистру.
        // - Значение: убираем пробелы по краям.
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string()))
        // Собираем все пары в HashMap
        .collect()
}
```

