        // Эти объекты создаются и умирают очень быстро.
        // Сборщик мусора будет часто проверять Gen 0.
        for (int i = 0; i < 1000; i++)
        {
            // Каждый цикл создает новый объект в Gen 0.
            // После цикла объект становится мусором.
            var temp = new byte[1024]; // ~1 КБ данных
            // temp больше не используется — он кандидат на удаление
        }
        // Здесь сработает быстрая сборка (Minor GC),
        // которая проверит только Gen 0. Это дешево.

