import reactor.core.publisher.FluxSink;
import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;

public class BackpressureExample {
    public static void main(String[] args) {
        // 1. Создаем быстрый источник данных (производитель)
        // Он генерирует 1000 элементов очень быстро
        Flux<Integer> fastSource = Flux.range(1, 1000)
            .delayElements(Duration.ofMillis(1)); // небольшой задерживаемый поток

        // 2. Создаем медленный потребителя
        // Он обрабатывает каждый элемент с задержкой в 100 мс
        AtomicInteger processedCount = new AtomicInteger(0);

        fastSource
            // 3. Устанавливаем стратегию backpressure:
            //    - backpressure() — по умолчанию, использует буфер
            //    - request(n) — потребитель запрашивает n элементов
            .subscribe(
                // onNext: вызывается для каждого элемента
                item -> {
                    // Имитируем медленную обработку
                    try {
                        Thread.sleep(100); // 100 мс на обработку
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                    processedCount.incrementAndGet();
                    System.out.println("Обработан элемент: " + item +
                        " (всего обработано: " + processedCount.get() + ")");
                },
                // onError: вызывается при ошибке
                error -> System.err.println("Ошибка: " + error.getMessage()),
                // onComplete: вызывается при завершении потока
                () -> System.out.println("Поток завершён. Обработано элементов: " +
                    processedCount.get())
            );
    }
}
```

